charts--line-from-csv.query:
// A line chart from a CSV file: loadcsv reads a table published next to the map, and afterCalc draws it in the panel - the CO2 emitted for each share of the forest cleared.
// The input holds a CsvTable: getLineCount() and getValue(column, line), columns by position.
// afterCalc runs once the expression's values are computed, so the layer needs one.
[
  {
    title: "Carbon stock, and the cost of clearing it",
    name: "CSR:biomassa_inv_br_redd",
    source: "calculate",
    opacity: 0.8,
    visibility: true,
    paramsButtonConfig: [{ type: "query", pressed: true }],
    descriptionHtml:
      "{{loadcsv|id=emissions|url=/theme/app/data/emissoesco2.csv}}" +
      '<div id="emissions_chart" style="width:290px;height:220px"></div>',
    expression: function (layersVals) {
      return layersVals[0];
    },
    afterCalc: function (inputs) {
      var table = inputs.id["emissions"];
      var points = [];
      for (var line = 0; line < table.getLineCount(); line++) {
        // column 0: share of the forest cleared (%); column 1: CO2 emitted (tonnes)
        var cleared = parseFloat(table.getValue(0, line));
        var emitted = parseFloat(table.getValue(1, line));
        if (isNaN(cleared) || isNaN(emitted)) continue; // e.g. the empty line a file ends with
        points.push([cleared, emitted / 1e9]);
      }
      var old = ExtjsUtils.HIGHCHART.getById("emissions_chart");
      if (old) old.destroy();
      Highcharts.chart("emissions_chart", {
        chart: { type: "line" },
        title: { text: "CO2 emitted by clearing the forest" },
        credits: { enabled: false },
        legend: { enabled: false },
        xAxis: { title: { text: "Forest cleared (%)" } },
        yAxis: { title: { text: "Billion tonnes of CO2" } },
        series: [{ name: "CO2 emitted", data: points }],
      });
    },
  },
];

