checkbox-widget--class-filters.query:
// Several switches, one filter: each checkbox turns one class of the map on or off - here dry, moderate and wet places by annual rainfall.
// Checkboxes are not inputs: one handler writes the state of the checkbox it is called for into an
// inputmanager (setValues merges keys and recalculates), and expression reads the three states.
[
  {
    title: "Rainfall classes",
    name: "CSR:precip_annual_average",
    source: "calculate",
    opacity: 0.85,
    visibility: true,
    paramsButtonConfig: [{ type: "query", pressed: true }],
    descriptionHtml:
      "{{inputmanager|id=classes}}" +
      "{{checkbox|id=show_dry|text=Dry: below 800 mm|checked=true|hideLabel=true|handler=onClassToggle}}" +
      "{{checkbox|id=show_moderate|text=Moderate: 800 to 1200 mm|checked=true|hideLabel=true|handler=onClassToggle}}" +
      "{{checkbox|id=show_wet|text=Wet: above 1200 mm|checked=true|hideLabel=true|handler=onClassToggle}}",
    functions: {
      // this = the layer; the checkbox's id names the class it switches
      onClassToggle: function (checkbox, checked) {
        var values = {};
        values[checkbox.id.replace("show_", "")] = checked;
        this.getInputs().id["classes"].setValues(values);
      },
    },
    onInputsReady: function (inputs) {
      inputs.id["classes"].setDefaultValues({ dry: true, moderate: true, wet: true });
    },
    // The legend lists only the classes shown. That also makes the layer recalculate: a change of
    // the inputs that leaves the legend as it was does not redraw the map.
    beforeCalc: function (inputs) {
      var show = inputs.id["classes"].global;
      var legend = [];
      if (show.dry) legend.push({ color: [230, 160, 40], value: 1, title: "Dry (below 800 mm)" });
      if (show.moderate) legend.push({ color: [120, 180, 90], value: 2, title: "Moderate (800 - 1200 mm)" });
      if (show.wet) legend.push({ color: [40, 110, 190], value: 3, title: "Wet (above 1200 mm)" });
      this.setCalculateLegend(legend);
    },
    expression: function (layersVals, inputs) {
      var show = inputs[0].global; // the inputmanager: the only input
      var rainfall = layersVals[0];
      if (!this.isNumeric(rainfall)) return this.nullValue;
      var rainClass = rainfall < 800 ? 1 : rainfall <= 1200 ? 2 : 3;
      var shown = rainClass === 1 ? show.dry : rainClass === 2 ? show.moderate : show.wet;
      return shown ? rainClass : this.nullValue;
    },
  },
];

checkbox-widget.query:
// Checkbox: not an input itself. Its handler stores the state in an inputmanager, whose
// plain "global" values are what reach expression() (inputs[0] - checkboxes take no position).
[
  {
    title: "Carbon-rich soils switch",
    name: "CSR:soil_organic_carbon_stock",
    source: "calculate",
    opacity: 0.85,
    visibility: true,
    paramsButtonConfig: [{ type: "query", pressed: true }],
    descriptionHtml:
      "{{checkbox|id=only_rich|text=Only soils above 50 Mg/ha|checked=true|hideLabel=true|handler=onToggle}}" +
      "{{inputmanager|id=state}}",
    functions: {
      // this = the layer; called with the checkbox and its new state
      onToggle: function (checkbox, checked) {
        this.getInputs().id["state"].setValues({ onlyRich: checked }); // recalculates
      },
    },
    onInputsReady: function (inputs) {
      inputs.id["state"].setDefaultValues({ onlyRich: true });
    },
    // The legend shows what the map shows - and changing it is what redraws the map: a change of
    // the inputs that leaves the legend as it was does not. The class always shown is value 1, the
    // optional one comes after it (legend values in ascending order).
    beforeCalc: function (inputs) {
      var legend = [{ color: [121, 85, 72], value: 1, title: "Above 50 Mg/ha" }];
      if (!inputs.id["state"].global.onlyRich) legend.push({ color: [241, 196, 15], value: 2, title: "Below 50 Mg/ha" });
      this.setCalculateLegend(legend);
    },
    expression: function (layersVals, inputs) {
      var onlyRich = inputs[0].global.onlyRich;
      if (layersVals[0] >= 50) return 1;
      return onlyRich ? this.nullValue : 2;
    },
  },
];

