expression-function--two-maps.query:
// Two maps in one expression: name lists both maps, and each pixel brings both values - here forest biomass, kept only where the land is low.
// layersVals follows the order of name: [0] the biomass (t/ha), [1] the elevation (m).
// A pixel where either map has no data is left out.
[
  {
    title: "Lowland forest biomass",
    name: "CSR:biomassa_baccini_bioma_am,CSR:altimetria",
    source: "calculate",
    opacity: 0.85,
    visibility: true,
    paramsButtonConfig: [{ type: "query", pressed: true }],
    descriptionHtml: "{{legendhtml}}",
    beforeCalc: function () {
      this.setCalculateLegend([
        { color: [22, 160, 133], value: 1, title: "Below 200 m, above 200 t/ha" },
        { color: [163, 228, 215], value: 2, title: "Below 200 m, up to 200 t/ha" },
      ]);
    },
    expression: function (layersVals) {
      var biomass = layersVals[0];
      var elevation = layersVals[1];
      if (!this.isNumeric(biomass) || !this.isNumeric(elevation)) return this.nullValue;
      if (elevation >= 200) return this.nullValue;
      return biomass > 200 ? 1 : 2;
    },
  },
];

