inputmanager-widget.query:
// InputManager: a named bag of values that buttons and callbacks fill; setValues() recalculates
// the layer. On the page use getValue(); in expression() read the plain values from .global.
[
  {
    title: "Vegetation biomass presets",
    name: "CSR:bioma_cerrado_biomassa",
    source: "calculate",
    opacity: 0.85,
    visibility: true,
    paramsButtonConfig: [{ type: "query", pressed: true }],
    descriptionHtml:
      "{{inputmanager|id=preset}}" +
      "{{button|id=preset_open|text=Open savanna (below 10 t/ha)|handler=showOpen}}" +
      "{{button|id=preset_wood|text=Woodland (above 50 t/ha)|handler=showWoodland}}",
    functions: {
      showOpen: function () {
        this.getInputs().id["preset"].setValues({ min: 0, max: 10, title: "Open savanna" });
      },
      showWoodland: function () {
        this.getInputs().id["preset"].setValues({ min: 50, max: 99999, title: "Woodland" });
      },
    },
    onInputsReady: function (inputs) {
      inputs.id["preset"].setDefaultValues({ min: 0, max: 10, title: "Open savanna" });
