mappia-io.query:
// MappiaIO, the map side of an embed: the query listens to the page that embeds it
// (setMappiaIoCallback) and answers it (postMessage). Both sides have buttons: the page's buttons
// send operations (list, show, add a city) and the panel shows what the page asked; the panel's
// own button and a click on a city report to the page. The operation names are this example's
// own - the platform reserves only the ones starting with "mappia__". On its own it is an
// ordinary map; the page side is on the MappiaIO page of the documentation.
ExtjsUtils.QUERY.setQueryGlobalProperties({
  citiesLayer: null, // set by onAdded below; cleared with the query like every global here
  onPageMessage: function (msg) {
    var layer = window.citiesLayer;
    if (!msg || !msg.operation || !layer) return; // not for this query, or not loaded yet
    var said = Ext.getCmp("page_said"); // the panel label: what the page asked last
    if (said) said.setText("The page asked: " + msg.operation + (msg.message && msg.message.name ? " " + msg.message.name : ""));
    var reply = { requestId: msg.requestId }; // echo the id so the page can match the answer
    if (msg.operation === "list_cities") {
      reply.operation = "cities";
      reply.message = layer.features.map(function (feature) { return feature.attributes; });
    } else if (msg.operation === "show_city") {
      var city = layer.features.filter(function (feature) {
        return feature.attributes.name === msg.message.name;
      })[0];
      if (city) {
        layer.map.setCenter(city.geometry.getBounds().getCenterLonLat(), 7);
        layer.selectController.unselectAll();
        layer.selectController.select(city);
      }
      reply.operation = "city_shown";
      reply.message = { name: msg.message.name, found: !!city };
    } else if (msg.operation === "add_city") {
      var point = new OpenLayers.Geometry.Point(msg.message.lon, msg.message.lat)
        .transform(new OpenLayers.Projection("EPSG:4326"), layer.map.getProjectionObject());
      layer.addFeatures([new OpenLayers.Feature.Vector(point, { name: msg.message.name, population: msg.message.population })]);
      reply.operation = "city_added";
      reply.message = { name: msg.message.name, count: layer.features.length };
    } else {
      reply.operation = "unknown_operation";
      reply.message = { operation: msg.operation };
    }
    ExtjsUtils.QUERY.postMessage(reply);
  },
  // map -> page from a button of the panel: {{button|handler=sendViewToPage}} finds it by name
  sendViewToPage: function () {
    var layer = window.citiesLayer;
    var view = layer.map.getExtent();
    var inView = layer.features.filter(function (feature) {
      return view.containsLonLat(feature.geometry.getBounds().getCenterLonLat());
    });
    ExtjsUtils.QUERY.postMessage({
      operation: "cities_in_view",
      message: { zoom: layer.map.getZoom(), cities: inView.map(function (feature) { return feature.attributes.name; }) },
    });
  },
}) &&
  ExtjsUtils.QUERY.setMappiaIoCallback(window.onPageMessage) && [
    {
      title: "Cities - talking to the page",
      name: "mappia_io_cities",
      source: "file",
      type: "json",
      fromProj: "EPSG:4326",
      visibility: true,
      paramsButtonConfig: [{ type: "query", pressed: true }],
      descriptionHtml:
        "{{label|id=page_said|text=Waiting for the page to send something.}}<br>" +
        "{{button|id=send_view|text=Send the cities in view to the page|handler=sendViewToPage}}",
      json: {
        type: "FeatureCollection",
        features: [
          ["Sao Paulo", -46.63, -23.55, 11451999],
          ["Rio de Janeiro", -43.2, -22.91, 6211423],
          ["Brasilia", -47.88, -15.79, 2817381],
          ["Fortaleza", -38.54, -3.73, 2428708],
          ["Salvador", -38.5, -12.97, 2417678],
          ["Belo Horizonte", -43.94, -19.92, 2315560],
          ["Manaus", -60.02, -3.12, 2063689],
          ["Curitiba", -49.27, -25.43, 1773718],
        ].map(function (city) {
          return {
            type: "Feature",
            properties: { name: city[0], population: city[3] },
            geometry: { type: "Point", coordinates: [city[1], city[2]] },
          };
        }),
      },
      defaultStyle: { graphicName: "circle", pointRadius: 9, fillColor: "#277cea", fillOpacity: 0.9, strokeColor: "#ffffff", strokeWidth: 2 },
      selectStyle: { pointRadius: 12, fillColor: "#e74c3c" },
      onAdded: function (event) {
