    opacity: 0.5,
  },
  {
    name: "CSR:biomassa_baccini_bioma_am",
    title: "Forest biomass (Amazon) - turn it on",
    visibility: false,
  },
];

tutorial-03-other-servers.query:
// Maps from another server: addRemoteWMSServer registers a map server under a name of your choice, and each layer names it in source.
// Here the server is a GitHub repository where maps were published with the Mappia QGIS plugin
// (storage: "github"); a classic WMS server is registered the same way, by its url.
// The registration comes first in the && chain, so the server is known when the layers are read.
ExtjsUtils.QUERY.addRemoteWMSServer({
  example_repo: {
    url: "https://github.com/asfixia/Mappia_Example/",
    storage: "github",
  },
}) && [
  {
    name: "GH:biome_amazon_am",
    source: "example_repo",
    title: "Amazon biome",
    visibility: true,
    opacity: 0.6,
  },
  {
    name: "GH:hydrography_am",
    source: "example_repo",
    title: "Rivers",
    visibility: true,
  },
  {
    name: "GH:major_roads",
    source: "example_repo",
    title: "Major roads",
    visibility: true,
  },
];

tutorial-04-source-types.query:
// Four kinds of source: a tile service (xyz), a published map (the default source), a calculated map (calculate) and features from a file (file), in one map.
// source says where a layer's pixels come from; the other properties of the layer depend on it.
[
  {
    title: "Terrain (xyz tiles)",
    name: "opentopomap",
    source: "xyz", // a tile service: ${z}, ${x} and ${y} are replaced for every tile
    url: "https://a.tile.opentopomap.org/${z}/${x}/${y}.png",
    visibility: true,
    opacity: 0.5,
  },
  {
    title: "States (published map)",
    name: "CSR:estados", // no source: a map of the catalogue, drawn by the map server
    visibility: true,
    opacity: 0.4,
  },
  {
    title: "Highlands (calculated)",
    name: "CSR:altimetria",
    source: "calculate", // the browser computes a new map from the values of the maps in name
    visibility: true,
    opacity: 0.8,
    beforeCalc: function () {
      this.setCalculateLegend([{ color: [160, 82, 45], value: 1, title: "Above 1000 m" }]);
    },
    expression: function (layersVals) {
      return layersVals[0] > 1000 ? 1 : this.nullValue;
    },
  },
  {
    title: "Two cities (file)",
    name: "two_cities",
    source: "file", // vector features: here written in the query (type json), in longitude / latitude
    type: "json",
    fromProj: "EPSG:4326",
    visibility: true,
    json: {
      type: "FeatureCollection",
      features: [
        { type: "Feature", properties: { name: "Belo Horizonte" }, geometry: { type: "Point", coordinates: [-43.94, -19.92] } },
        { type: "Feature", properties: { name: "Brasilia" }, geometry: { type: "Point", coordinates: [-47.88, -15.79] } },
      ],
    },
    defaultStyle: {
      graphicName: "circle",
      pointRadius: 9,
      fillColor: "#e74c3c",
      strokeColor: "#ffffff",
      strokeWidth: 2,
      label: "${name}", // an attribute of each feature, written on the map
      labelYOffset: -18,
      fontWeight: "bold",
      labelOutlineColor: "#ffffff",
      labelOutlineWidth: 3,
    },
  },
];

tutorial-05-calculated-map.query:
// A calculated map with a control: a slider feeds the expression, and moving it computes the map again.
// beforeCalc runs on the page before each calculation: there the inputs are read by id.
// expression runs in a separate worker, once per pixel: there the inputs are read by position
// (inputs[0] is the first input in descriptionHtml) - see the execution model.
[
  {
    title: "Land above an elevation",
    name: "CSR:altimetria",
    source: "calculate",
    visibility: true,
    opacity: 0.85,
    paramsButtonConfig: [{ type: "query", pressed: true }], // the panel with the controls starts open
    descriptionHtml:
      "{{label|text=Minimum elevation (m)}}" +
      "{{slider|id=minimum|minValue=0|maxValue=2000|increment=100|value=1000|width=250}}",
    beforeCalc: function (inputs) {
      this.setCalculateLegend([
        { color: [192, 57, 43], value: 1, title: "Above " + inputs.id["minimum"] + " m" },
      ]);
    },
    expression: function (layersVals, inputs) {
      return layersVals[0] >= inputs[0] ? 1 : this.nullValue;
    },
  },
];

tutorial-06-groups.query:
// Groups: viewTitle makes a group of the top menu, elements holds its layers, and defaultProperties is shared by every layer inside.
// The layers of a group show when its menu is open; openGroup starts it open. A layer sets a
// property itself to differ from defaultProperties (Elevation starts visible below).
[
  {
    viewTitle: "Relief",
    color: "#8d4925",
    openGroup: true,
    defaultProperties: { visibility: false, opacity: 0.7 },
    elements: [
      { title: "Elevation", name: "CSR:altimetria", visibility: true },
      { title: "Slope (Cerrado)", name: "CSR:bioma_cerrado_declividade" },
    ],
  },
  {
    viewTitle: "Boundaries",
    color: "#2c3e50",
    elements: [
      { title: "States", name: "CSR:estados", visibility: true, opacity: 0.5 },
    ],
  },
];

tutorial-07-globals-and-functions.query:
// Globals and functions: setQueryGlobalProperties declares the names the query shares, runNow runs once when the query is applied, and buttons call functions by name.
// A query is one expression, so it cannot declare variables with var: setQueryGlobalProperties
// puts each key on window while this query is applied, and returns true, so the && chain goes on
// to the layers. A button's handler is looked up in the layer's functions first (this = the
// layer), then among the globals.
ExtjsUtils.QUERY.setQueryGlobalProperties({
  CAPITAL: { name: "Brasilia", lon: -47.88, lat: -15.79 },
  // the one name the platform calls by itself, once, after the globals are in place
  runNow: function () {
    ExtjsUtils.ALERTIFY.log("The query is applied - press the buttons in the panel.");
  },
  goToCapital: function () {
    var map = ExtjsUtils.JS.getMap();
    var center = new OpenLayers.LonLat(CAPITAL.lon, CAPITAL.lat)
      .transform(new OpenLayers.Projection("EPSG:4326"), map.getProjectionObject());
    map.setCenter(center, 9);
    ExtjsUtils.ALERTIFY.log("Here is " + CAPITAL.name + ".");
  },
}) && [
  {
    title: "States",
    name: "CSR:estados",
    source: "calculate",
    visibility: true,
    opacity: 0.5,
    paramsButtonConfig: [{ type: "query", pressed: true }],
    descriptionHtml:
      "{{button|id=go_capital|text=Go to the capital|handler=goToCapital}}" + // a global function
      "{{button|id=which_layer|text=Which layer is this?|handler=sayTitle}}", // a function of the layer
    functions: {
      sayTitle: function () {
        ExtjsUtils.ALERTIFY.log("This button belongs to the layer \"" + this.title + "\".");
      },
    },
  },
];

tutorial-08-extjsutils.query:
// The ExtjsUtils toolbox: the platform's helpers your code calls - here to talk to the reader, read a layer's legend and move the map.
// ExtjsUtils.ALERTIFY shows messages and questions, ExtjsUtils.LAYER reads layers and legends,
// ExtjsUtils.JS.getMap() is the map itself (OpenLayers), ExtjsUtils.QUERY applies, adds and
// removes layers. The API reference lists every helper of each group.
ExtjsUtils.QUERY.setQueryGlobalProperties({
  REGIONS: {
    North: [-74, -10, -46, 5],
    Northeast: [-48, -18, -34, -1],
    South: [-58, -34, -47, -22],
  },
}) && [
  {
    title: "Elevation",
    name: "CSR:altimetria",
    source: "calculate",
    visibility: true,
    opacity: 0.8,
    paramsButtonConfig: [{ type: "query", pressed: true }],
    descriptionHtml:
      "{{button|id=read_legend|text=Read the legend|handler=readLegend}}" +
      "{{button|id=choose_region|text=Go to a region|handler=chooseRegion}}",
    functions: {
      readLegend: function () {
        var entries = ExtjsUtils.LAYER.getLayerLegend(this, 0); // the legend of this layer's first map
        ExtjsUtils.ALERTIFY.log("<b>" + entries.length + " classes</b>, from " +
          entries[0].title + " to " + entries[entries.length - 1].title + ".");
      },
      chooseRegion: function () {
        ExtjsUtils.ALERTIFY.confirmChoice(
          "Which region should the map show?",
          Object.keys(REGIONS).map(function (name) { return { label: name, value: name }; }),
          function (name) {
            var map = ExtjsUtils.JS.getMap();
            var box = REGIONS[name];
            map.zoomToExtent(new OpenLayers.Bounds(box[0], box[1], box[2], box[3])
              .transform(new OpenLayers.Projection("EPSG:4326"), map.getProjectionObject()));
          }
        );
      },
    },
  },
];
